function persistLibrary(next){if(libraryBlocked)throw Error('저장된 목록을 읽지 못해 덮어쓰기를 막았습니다. 공략 파일로 보관하세요.');const current=localStorage.getItem(J.GUIDES_KEY)||'[]';if(current!==libraryRaw)throw Error('다른 화면에서 공략 목록이 변경되었습니다. 새로고침 후 다시 시도하세요.');if(next.length>30)throw Error('내 공략은 30개까지 저장합니다. 파일로 보관한 뒤 필요 없는 항목을 삭제하세요.');const text=JSON.stringify(next);localStorage.setItem(J.GUIDES_KEY,text);libraryRaw=text;library=next;renderLibrary();}
let libraryRaw='[]';
