function renderLibrary(){const box=$('#guide-library');box.replaceChildren();if(!library.length)box.append(el('p','아직 저장한 공략이 없습니다. 작성하거나 가져온 공략을 미리보기에서 저장하세요.','muted'));library.forEach((value,index)=>{const card=el('article',undefined,'guide-card');card.append(el('h3',value.title),el('p',J.MODES[value.mode]+' · '+value.wave+'R'));const actions=el('div',undefined,'journey-actions');actions.append(button('열기·편집',()=>{fillGuide(value);preview(value);status('공략을 불러왔습니다. 편집 후 코드 만들기를 누르면 변경된 내용으로 생성합니다.');}),button('코드 복사',()=>copy(J.encode(value))),button('파일 저장',()=>download(value,'stack-lab-guide.json')),button('내 목록에서 삭제',()=>{try{persistLibrary(library.filter((_,i)=>i!==index));status('내 공략 목록에서 삭제했습니다.');}catch(error){status(error.message);}}));card.append(actions);box.append(card);});}
