function fillGuide(value,post=null){editingPost=post;editorDeck=structuredClone(value.deck);for(const [id,key]of [['guide-title','title'],['guide-operation','operation'],['guide-requirements','requirements'],['guide-alternatives','alternatives'],['guide-mode','mode'],['guide-wave','wave']])$('#'+id).value=value[key];$('#guide-wave').max=T.lastWave(value.mode);$('#guide-deck-source').textContent='작성 덱: 가져온 공략의 덱 (현재 저장 덱과 별도)';$('#guide-form button[type=submit]').textContent=post?'수정 미리보기 만들기':'게시글 미리보기 만들기';if($('#guide-editor')){$('#guide-editor').open=true;$('#guide-title').focus({preventScroll:true});}}
